import { rsvpToEvent } from '../api/eventApi';

const EventCard = ({ event }) => {
    const dummyUserId = "661e9c20f1e68a0c4cbf55a2"; // Replace with real user ID logic later
    const handleRSVP = async () => {
        try {
            await rsvpToEvent(event._id, dummyUserId);
            window.location.reload();
        } catch (err) {
            console.error("RSVP error:", err);
        }
    };

    return (
        <div className="event-card">
            <h3>{event.name}</h3>
            <p>{event.description}</p>
            <p>📍 {event.location} | 📅 {new Date(event.date).toDateString()}</p>
            <p>🎟 {event.attendees.length}/{event.maxAttendees} Attendees</p>
            <button onClick={handleRSVP} disabled={event.attendees.length >= event.maxAttendees}>RSVP</button>
        </div>
    );
};

export default EventCard;
